#!/usr/bin/env python3
"""Minimal LLM call against the Zoom LLM gateway.

Mirrors api_test.bash. Reads the API key from the APIKEY env var.

Usage:
    export APIKEY=...
    python llm_call.py "Who are you?"
    python llm_call.py --model gpt-5.5 "Who are you?"
"""
import argparse
import os
import sys

import requests

BASE_URL = "https://llm-gateway-colo01-colo.zoomdev.us/v1/chat/completions"


def chat(prompt, model="gpt-5.5", api_key=None, base_url=BASE_URL, timeout=120):
    api_key = api_key or os.environ.get("APIKEY")
    if not api_key:
        raise RuntimeError("Set the APIKEY environment variable or pass api_key.")

    resp = requests.post(
        base_url,
        headers={
            "X-Api-Key": api_key,
            "Content-Type": "application/json",
        },
        json={
            "model": model,
            "messages": [{"role": "user", "content": prompt}],
        },
        timeout=timeout,
    )
    resp.raise_for_status()
    data = resp.json()
    return data["choices"][0]["message"]["content"]


def main():
    model = "gpt-5.5"
    prompt = "You are preparing a grading rubric for hard math problems in a math exam.\n\nYour task is to produce:\n1. A correct, self-contained reference solution.\n2. A hierarchical decomposition of that solution into grading units.\n\nThink of the decomposition the way a good math homework solution is structured: the big problem is broken into a small number of natural subproblems, and each subproblem is supported by a few checkable lines. A grader (or a student reading it) should see \"to solve this, you do these few things, and within each you must reach these specific checkpoints.\"\n\nThe decomposition has two levels:\n\nLevel 1: Major reasoning procedures (the subproblems)\n- These are the main phases of the solution.\n- Each major procedure groups together several related mathematical moves into one natural subproblem.\n- A typical hard problem should have about 4 to 7 major procedures.\n- A major procedure should be broad enough that a grader could assign coarse credit for it.\n- Do not make one major procedure for every algebraic manipulation. If there are more than 7, merge related ones.\n\nLevel 2: Substeps inside each major procedure (the checkable lines)\n- Use AS FEW SUBSTEPS AS POSSIBLE. A substep should only exist if it is a milestone a grader can locate and tick on its own.\n- Default to 1 to 3 substeps per major procedure. Use more only when there is genuine case analysis.\n- Never split a single chain of algebra into multiple substeps. Collapse sequential manipulation into at most one intermediate checkpoint plus the final expression. If there is no meaningful intermediate worth ticking, use a single substep that states the result.\n- If two candidate substeps would always be earned together, merge them into one.\n- Substeps must be mathematically specific: exact formulas, derived equations, substitutions, or case eliminations.\n- Put the final checkable expression of the procedure as the last substep.\n- If a major procedure includes genuine case discussion, list each case's checkable conclusion as a substep (this is the one situation where more substeps are warranted).\n\nVerification:\n- Verify the final answer yourself to be sure the solution is correct, and you may mention the check briefly inside \"reference_solution\".\n- Do NOT create a major procedure, or a substep, whose only job is to verify or sanity-check the final answer. A student's graded solution is the reasoning that produces and justifies the answer, not a redundant post-hoc check (\"plug the answer back in and confirm\").\n- Important distinction: a logically necessary check is NOT a verification step and must stay as a substep where it belongs, for example excluding extraneous roots, confirming which case is the geometrically valid one, or discarding candidates that violate a stated constraint. Only the redundant final re-check is dropped.\n\nImportant distinction between student-facing and grader-facing fields:\n- The \"purpose\" field is student-facing. It may be shown to a student as a hint.\n- The \"core_conclusion\" and the \"substeps\" are grader-facing. They may contain exact formulas, equations, values, and case eliminations.\n\nHow to write the \"purpose\" field (student-facing hint):\n- Write it as the single sentence a teacher would say to a student who has finished the previous major procedures and is now stuck on how to start this one.\n- It should unstick the student by naming the strategy to use, the tool or theorem to reach for, the condition to exploit, or the quantity to focus on.\n- It must be actionable and forward-looking: \"Set up...\", \"Use the condition that...\", \"Reduce the system to...\", \"Use the fact that D lies outside the triangle to...\".\n- It must NOT contain any equation, numeric value, candidate set, factorization, or final result. Those live only in \"core_conclusion\" and \"substeps\".\n- Self-test: if reading the \"purpose\" alone hands the student the answer to this subproblem, it is too revealing, so rewrite it as a direction, not a result.\n\nGood examples of \"purpose\":\n- \"Choose a coordinate setup that makes the angle bisector easy to use.\"\n- \"Translate the two geometric constraints involving D into algebraic equations.\"\n- \"Reduce the system to a single quantity that directly determines the desired length.\"\n- \"Use the fact that D is outside the triangle to select the geometrically valid case.\"\n- \"Compute the requested expression for the configuration you have selected.\"\n\nBad examples of \"purpose\":\n- \"Show that tan(A/2)=1/2 and write B=(2u,u), C=(2v,-v).\"\n- \"Derive 3uv-2(u+v)+1=0 and 4(5u^2-4u+1)=9(5v^2-4v+1).\"\n- \"Find P=11/18.\"\n- \"Conclude that a+b+c=34.\"\n\nThe grader should be able to use:\n- only the major procedures for a coarse rubric,\n- the \"purpose\" fields as student hints, or\n- the substeps for a finer grading rubric.\n\nThe desired style is shown in the one-shot example below. The example is only for format, granularity, and style. Do not copy its mathematical content unless it is relevant to the actual problem.\n\n===== ONE-SHOT EXAMPLE =====\n\nExample problem:\nIn the country Máxico, there are two islands: the island \"Mayor\" and the island \"Menor\". The island \"Mayor\" has k > 3 states, with exactly n > 3 cities in each state. The island \"Menor\" has only one state with 31 cities. \"Aeropapantla\" and \"Aerocenzontle\" are the airlines that offer flights in Máxico. \"Aeropapantla\" offers direct flights from every city in Máxico to any other city in Máxico. \"Aerocenzontle\" only offers direct flights from every city on the island \"Mayor\" to any other city on the island \"Mayor\". If the percentage of flights that connect two cities in the same state is the same for the flights of each airline, what is the least number of cities that can be on the island \"Mayor\"?\n\nExample output:\n<output>\n{\n  \"reference_solution\": \"Let m=kn be the number of cities on Mayor. For Aerocenzontle, flights occur only among the m cities of Mayor. The same-state flights are those within each of the k states, so the fraction of same-state flights is k n(n-1)/(kn(kn-1))=(n-1)/(kn-1)=(n-1)/(m-1). For Aeropapantla, flights occur among all m+31 cities in Máxico. Same-state flights consist of the k states on Mayor plus the single state on Menor, so the fraction is (k n(n-1)+31·30)/((kn+31)(kn+30))=(m(n-1)+930)/((m+31)(m+30)). Since the percentages are equal, (m(n-1)+930)/((m+31)(m+30))=(n-1)/(m-1). Cross-multiplying gives (m(n-1)+930)(m-1)=(n-1)(m+31)(m+30). Expanding and canceling m^2(n-1) gives 930m-930=62m(n-1)+930(n-1). Dividing by 62, 15(m-1)=(n-1)(m+15). This simplifies to m(16-n)=15n, so m=15n/(16-n). Since k=m/n=15/(16-n) must be an integer greater than 3 and n>3, the positive integer 16-n must divide 15 and be less than 15/3. The possible divisors are 1, 3, and 5, giving k=15, 5, and 3 respectively. Since k>3, only k=15 or k=5 are allowed. These correspond to n=15 and n=13, giving m=225 and m=65. The least possible number of cities on Mayor is therefore 65. (As a check, for n=13, k=5 both airlines have same-state fraction 3/16, so 65 is valid.)\",\n  \"major_steps\": [\n    {\n      \"step_id\": 1,\n      \"title\": \"Compute the same-state flight fraction for Aerocenzontle\",\n      \"purpose\": \"Model the airline that flies only within Mayor, and express the quantity the problem compares: its share of same-state flights, in terms of the number of cities per state and the total size of Mayor.\",\n      \"core_conclusion\": \"Aerocenzontle's same-state flight fraction is (n-1)/(m-1), where m=kn.\",\n      \"difficulty\": \"easy\",\n      \"substeps\": [\n        {\n          \"substep_id\": \"1.1\",\n          \"operation\": \"With m=kn, count Aerocenzontle's flights among Mayor's cities: kn(kn-1) total and k·n(n-1) same-state (ordered flights, or unordered pairs with the same ratio).\",\n          \"difficulty\": \"easy\"\n        },\n        {\n          \"substep_id\": \"1.2\",\n          \"operation\": \"Simplify the same-state share to (n-1)/(m-1).\",\n          \"difficulty\": \"easy\"\n        }\n      ],\n      \"acceptable_variants\": \"A student may count unordered pairs instead of ordered flights, as long as the same ratio (n-1)/(m-1) is obtained.\"\n    },\n    {\n      \"step_id\": 2,\n      \"title\": \"Compute the same-state flight fraction for Aeropapantla\",\n      \"purpose\": \"Do the same for the airline that flies among every city in Máxico, remembering to include the extra state on Menor.\",\n      \"core_conclusion\": \"Aeropapantla's same-state flight fraction is (m(n-1)+930)/((m+31)(m+30)).\",\n      \"difficulty\": \"easy\",\n      \"substeps\": [\n        {\n          \"substep_id\": \"2.1\",\n          \"operation\": \"Count Aeropapantla's flights among all m+31 cities: (m+31)(m+30) total, with same-state flights m(n-1) from Mayor plus 31·30=930 from Menor.\",\n          \"difficulty\": \"easy\"\n        },\n        {\n          \"substep_id\": \"2.2\",\n          \"operation\": \"Write the same-state share as (m(n-1)+930)/((m+31)(m+30)).\",\n          \"difficulty\": \"easy\"\n        }\n      ],\n      \"acceptable_variants\": \"A student may use unordered pairs throughout, as long as the same fraction is obtained consistently.\"\n    },\n    {\n      \"step_id\": 3,\n      \"title\": \"Use the equal-percentage condition to derive a Diophantine relation\",\n      \"purpose\": \"Translate the condition that the two shares are equal into a single clean relation between the unknowns.\",\n      \"core_conclusion\": \"The equality simplifies to m(16-n)=15n.\",\n      \"difficulty\": \"moderate\",\n      \"substeps\": [\n        {\n          \"substep_id\": \"3.1\",\n          \"operation\": \"Set the two shares equal and cross-multiply: (m(n-1)+930)(m-1)=(n-1)(m+31)(m+30).\",\n          \"difficulty\": \"easy\"\n        },\n        {\n          \"substep_id\": \"3.2\",\n          \"operation\": \"Expand, cancel, and simplify to m(16-n)=15n.\",\n          \"difficulty\": \"moderate\"\n        }\n      ],\n      \"acceptable_variants\": \"Equivalent simplified equations should receive credit, for example m=15n/(16-n) or k=15/(16-n).\"\n    },\n    {\n      \"step_id\": 4,\n      \"title\": \"Apply the integer constraints and minimize the number of cities\",\n      \"purpose\": \"Use the size and integer constraints on the number of states and cities to pin down the finitely many possibilities and choose the smallest.\",\n      \"core_conclusion\": \"The allowed values give m=225 or m=65, so the least possible value is 65.\",\n      \"difficulty\": \"moderate\",\n      \"substeps\": [\n        {\n          \"substep_id\": \"4.1\",\n          \"operation\": \"From m=kn and m(16-n)=15n, obtain k=15/(16-n).\",\n          \"difficulty\": \"moderate\"\n        },\n        {\n          \"substep_id\": \"4.2\",\n          \"operation\": \"Require k to be a positive integer with k>3 and n>3, so 16-n is a divisor of 15; this leaves (n,k)=(15,15) and (13,5) after excluding the divisor giving k=3.\",\n          \"difficulty\": \"moderate\"\n        },\n        {\n          \"substep_id\": \"4.3\",\n          \"operation\": \"Compute m for the surviving cases (225 and 65) and take the least: m=65.\",\n          \"difficulty\": \"easy\"\n        }\n      ],\n      \"acceptable_variants\": \"A student may enumerate n directly instead of using divisors of 15, as long as all integer constraints are applied. A brief check that both shares equal 3/16 may appear in the write-up but is not required for credit.\"\n    }\n  ]\n}\n</output>\n\n===== ACTUAL TASK =====\n\nProblem:\nAn arrangement of 12 real numbers in a row is called *good* if for any four consecutive numbers, the arithmetic mean of the first and last numbers is equal to the product of the two middle numbers. Determine how many good arrangements exist in which the first and last numbers are 1, and the second number is the same as the third.\n\nKnown answer, if available:\n45\n\nInstructions:\n- Solve the problem carefully from first principles.\n- If a known answer is provided, use it only as a consistency check. Do not force the solution to match it if it appears incorrect.\n- Verify the final answer yourself for correctness; you may note the check briefly inside \"reference_solution\", but do not add a verification major step or a verification substep.\n- Decompose the solution into hierarchical grading criteria, like the subproblems of a good homework solution.\n- Major procedures should represent the main structure of the solution, not individual algebraic manipulations.\n- Substeps should represent meaningful, checkable mathematical claims, and there should be as few of them as possible.\n- Major procedures should usually be fewer and broader than substeps.\n- A hard problem should usually have 4 to 7 major procedures.\n- Each major procedure should usually contain 1 to 3 substeps; use more only when there is genuine case analysis.\n- Steps should be ordered logically.\n- The decomposition should be compatible with equivalent student solutions where possible.\n- Include notes about acceptable equivalent methods when helpful.\n- Do not include trivial formatting, restatement of the problem, or unexplained jumps as steps.\n- Use valid JSON only: true/false/null must be lowercase; no trailing commas; no comments.\n- Output exactly one JSON object inside the <output>...</output> tags.\n- Do not include markdown or any text outside the <output> tags.\n\nDifficulty labels:\n- \"easy\": routine observation, direct substitution, simple algebra, or immediate recall\n- \"moderate\": nontrivial transformation, standard theorem, or multi-line inference\n- \"hard\": key insight, delicate argument, construction, proof idea, or subtle case analysis\n\nRequired output format:\n<output>\n{\n  \"reference_solution\": \"Complete, self-contained reference solution. Include verification within the prose if useful, and clearly state the final answer.\",\n  \"major_steps\": [\n    {\n      \"step_id\": 1,\n      \"title\": \"Short name for the major reasoning procedure.\",\n      \"purpose\": \"Student-facing hint: what direction to take in this subproblem, without revealing any equation, value, or result.\",\n      \"core_conclusion\": \"The main mathematical result obtained by this procedure.\",\n      \"difficulty\": \"easy/moderate/hard\",\n      \"substeps\": [\n        {\n          \"substep_id\": \"1.1\",\n          \"operation\": \"Concrete, checkable substep within this major procedure.\",\n          \"difficulty\": \"easy/moderate/hard\"\n        }\n      ],\n      \"acceptable_variants\": \"Brief note about equivalent approaches a student might use, or null if unnecessary.\"\n    }\n  ]\n}\n</output>"

    try:
        print(chat(prompt, model=model))
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()
